class Solution:
    def countSteppingNumbers(self, low: int, high: int) -> List[int]:
        def ok(n):
            s = str(n)
            return all(abs(int(s[i]) - int(s[i+1])) == 1 for i in range(len(s)-1))
        return [n for n in range(low, high + 1) if ok(n)]

