class Solution {
public:
    vector<int> countSteppingNumbers(int low, int high) {
        vector<int> res;
        auto ok = [](long long n) {
            long long p = n % 10;
            n /= 10;
            while (n > 0) {
                long long c = n % 10;
                if (abs(c - p) != 1) return false;
                p = c; n /= 10;
            }
            return true;
        };
        for (long long n = low; n <= high; n++)
            if (ok(n)) res.push_back((int)n);
        return res;
    }
};

