class Solution {
    public List<Integer> countSteppingNumbers(long low, long high) {
        List<Integer> res = new ArrayList<>();
        for (long n = low; n <= high; n++) {
            if (ok(n)) res.add((int) n);
        }
        return res;
    }
    private boolean ok(long n) {
        long p = n % 10;
        n /= 10;
        while (n > 0) {
            long c = n % 10;
            if (Math.abs(c - p) != 1) return false;
            p = c; n /= 10;
        }
        return true;
    }
}

