        res = [] if low > 0 else [0]
        q = deque(range(1, 10))
        while q:
            x = q.popleft()
            d = x % 10
            for nd in (d - 1, d + 1):
                if 0 <= nd <= 9:
                    y = x * 10 + nd
                    if y > high:
                        continue
                    if y >= low:
                        res.append(y)
                    q.append(y)
