class Solution {
    public List<Integer> countSteppingNumbers(long low, long high) {
        List<Long> res = new ArrayList<>();
        if (low == 0) res.add(0L);
        Queue<Long> q = new LinkedList<>();
        for (long i = 1; i <= 9; i++) q.offer(i);
        while (!q.isEmpty()) {
            long x = q.poll();
            int d = (int)(x % 10);
            for (int nd : new int[]{d - 1, d + 1}) {
                if (nd < 0 || nd > 9) continue;
                long y = x * 10 + nd;
                if (y > high) continue;
                if (y >= low) res.add(y);
                q.offer(y);
            }
        }
        Collections.sort(res);
        List<Integer> out = new ArrayList<>();
        for (long v : res) out.add((int) v);
        return out;
    }
}

