var countSteppingNumbers = function(low, high) {
    const res = low === 0 ? [0] : [];
    const q = [1,2,3,4,5,6,7,8,9];
    let head = 0;
    while (head < q.length) {
        const x = q[head++];
        const d = x % 10;
        for (const nd of [d - 1, d + 1]) {
            if (nd < 0 || nd > 9) continue;
            const y = x * 10 + nd;
            if (y > high) continue;
            if (y >= low) res.push(y);
            q.push(y);
        }
    }
    return res.sort((a, b) => a - b);
};
